/**
 * Open a URL in the user's default browser. Falls back to printing the
 * URL when no browser is openable (SSH session, CI, `BROWSER=none`,
 * or `open` rejects).
 */

import { c } from "../ui/colors.js";
import { normalizeErrorMessage } from "../utils/errorMessage.js";

export interface OpenBrowserResult {
  /** True when we successfully invoked the platform "open" command. */
  opened: boolean;
}

export async function openBrowser(url: string): Promise<OpenBrowserResult> {
  if (process.env["BROWSER"] === "none" || process.env["HF_NO_BROWSER"] === "1") {
    printManualInstructions(url);
    return { opened: false };
  }
  try {
    const open = (await import("open")).default;
    await open(url);
    return { opened: true };
  } catch (err) {
    printManualInstructions(url, normalizeErrorMessage(err));
    return { opened: false };
  }
}

function printManualInstructions(url: string, detail?: string): void {
  if (detail) {
    console.error(c.warn(`Could not open browser automatically (${detail}).`));
  } else {
    console.error(c.warn("Browser auto-open is disabled."));
  }
  console.error(`Open this URL manually to continue:\n  ${c.accent(url)}`);
}

/**
 * Authored-opacity contract, studio side. The runtime stamps every graded
 * element's authored inline opacity at document parse time (see
 * installAuthoredOpacityCapture in @hyperframes/core); studio code that makes
 * GSAP re-initialize tweens (soft reload, in-place patches) restores it so
 * re-captures never bake a runtime transient in as a tween bound.
 */
import { COLOR_GRADING_AUTHORED_OPACITY_ATTR } from "@hyperframes/core/color-grading";

interface AttributeReader {
  getAttribute(name: string): string | null;
}

/**
 * The stamped authored inline opacity. Three-state:
 *   "0.98" — the authored value; "" — captured, authored none;
 *   null — never captured (unknown).
 * Duck-typed so iframe-realm elements (no shared HTMLElement) work.
 */
export function readStampedAuthoredOpacity(element: AttributeReader): string | null {
  return element.getAttribute(COLOR_GRADING_AUTHORED_OPACITY_ATTR);
}

/**
 * Write an authored inline opacity back: "" removes the property, a value sets
 * it. Priority-lossy by design: the capture reads `style.opacity` (value only)
 * and the write sets no priority, so an authored `opacity: X !important`
 * round-trips as `opacity: X`. The only `!important` opacity in the pipeline
 * is the color-grading runtime hide — a transient this contract exists to
 * discard — and authored compositions don't `!important` their opacity.
 */
export function applyAuthoredInlineOpacity(style: CSSStyleDeclaration, authored: string): void {
  if (authored === "") style.removeProperty("opacity");
  else style.setProperty("opacity", authored);
}

/**
 * `deploySite` — upload a project directory to GCS once per content hash
 * and return a reusable handle.
 *
 * `renderToCloudRun` calls this implicitly when no `siteHandle` is passed,
 * but exposing it as a standalone verb lets adopters bundle a project ahead
 * of time and reuse the handle across many renders without re-tarring the
 * project tree on every call.
 *
 * The handle is **content-addressed**: `siteId` is derived from a SHA-256
 * over the project files. Two `deploySite` calls on an unchanged tree
 * produce the same `siteId` and short-circuit the upload after a single
 * existence check.
 */

import { mkdtempSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Storage } from "@google-cloud/storage";
import { hashProjectDir } from "@hyperframes/producer/distributed";
import { formatGcsUri, tarDirectory, uploadFileToGcs } from "../gcsTransport.js";

/** Options for {@link deploySite}. */
export interface DeploySiteOptions {
  /** Local project directory containing `index.html` (and any composition assets). */
  projectDir: string;
  /** GCS bucket the Terraform module provisioned. */
  bucketName: string;
  /**
   * Override the content-addressed site id. Useful when the caller has a
   * stable external identifier they want to use (e.g. a git SHA); if unset,
   * the hash of the project tree picks it.
   */
  siteId?: string;
  /** Injection seam for tests. Production callers leave unset. */
  storage?: Storage;
}

/** Stable handle returned by {@link deploySite}. Pass back to {@link renderToCloudRun}. */
export interface SiteHandle {
  /** Content-addressed (or caller-supplied) identifier; stable across re-uploads of the same tree. */
  siteId: string;
  /** Bucket the site landed in. Surfaced separately so callers don't have to re-parse `projectGcsUri`. */
  bucketName: string;
  /** Full `gs://bucket/sites/<siteId>/project.tar.gz` URI; pass through to `renderToCloudRun`. */
  projectGcsUri: string;
  /** Tarball size in bytes; useful for "did we actually skip the upload?" assertions. */
  bytes: number;
  /** ISO timestamp of the most recent upload OR the existing object the short-circuit found. */
  uploadedAt: string;
  /** `false` if the object already existed and we skipped the upload. */
  uploaded: boolean;
}

/**
 * Upload `projectDir` to `gs://bucketName/sites/<siteId>/project.tar.gz`.
 *
 * Short-circuits when an object with the same key already exists in the
 * bucket — `siteId` derives from the project's content hash, so the same
 * bytes produce the same key, and re-uploading would be redundant.
 */
// fallow-ignore-next-line complexity
export async function deploySite(opts: DeploySiteOptions): Promise<SiteHandle> {
  if (!statSync(opts.projectDir).isDirectory()) {
    throw new Error(`[deploySite] projectDir is not a directory: ${opts.projectDir}`);
  }

  const siteId = opts.siteId ?? hashProjectDir(opts.projectDir);
  const key = `sites/${siteId}/project.tar.gz`;
  const projectGcsUri = formatGcsUri({ bucket: opts.bucketName, key });
  const storage = opts.storage ?? new Storage();
  const file = storage.bucket(opts.bucketName).file(key);

  // Existence short-circuit. Adopters re-rendering the same project on a
  // tight inner loop (CI smoke, demo flows) save the tar+gzip+upload pass
  // on every iteration.
  const existing = await headObject(file);
  if (existing) {
    return {
      siteId,
      bucketName: opts.bucketName,
      projectGcsUri,
      bytes: existing.bytes,
      uploadedAt: existing.lastModified,
      uploaded: false,
    };
  }

  const workdir = mkdtempSync(join(tmpdir(), "hf-deploy-site-"));
  try {
    const tarball = join(workdir, "project.tar.gz");
    await tarDirectory(opts.projectDir, tarball);
    const size = statSync(tarball).size;
    await uploadFileToGcs(storage, tarball, projectGcsUri, "application/gzip");
    return {
      siteId,
      bucketName: opts.bucketName,
      projectGcsUri,
      bytes: size,
      uploadedAt: new Date().toISOString(),
      uploaded: true,
    };
  } finally {
    rmSync(workdir, { recursive: true, force: true });
  }
}

/**
 * Narrow surface of the `@google-cloud/storage` `File` this module uses —
 * lets the test double implement just `exists()` + `getMetadata()` without
 * pulling the full client type.
 */
interface FileLike {
  exists(): Promise<[boolean, ...unknown[]]>;
  getMetadata(): Promise<[{ size?: string | number; updated?: string }, ...unknown[]]>;
}

// fallow-ignore-next-line complexity
async function headObject(file: FileLike): Promise<{ bytes: number; lastModified: string } | null> {
  const [exists] = await file.exists();
  if (!exists) return null;
  const [meta] = await file.getMetadata();
  const sizeRaw = meta.size;
  const bytes =
    typeof sizeRaw === "string" ? Number(sizeRaw) : typeof sizeRaw === "number" ? sizeRaw : 0;
  return {
    bytes: Number.isFinite(bytes) ? bytes : 0,
    lastModified: meta.updated ?? new Date().toISOString(),
  };
}

/**
 * `deploySite` — upload a project directory to S3 once per content hash
 * and return a reusable handle.
 *
 * `renderToLambda` calls this implicitly when no `siteHandle` is passed,
 * but exposing it as a standalone verb lets adopters bundle a project
 * ahead of time and reuse the handle across many renders without
 * re-tarring the project tree on every call.
 *
 * The handle is **content-addressed**: `siteId` is derived from a SHA-256
 * over the project files. Two `deploySite` calls on an unchanged tree
 * produce the same `siteId` and `HeadObject`-short-circuit the upload.
 */

import { mkdtempSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { HeadObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { hashProjectDir } from "@hyperframes/producer/distributed";
import { formatS3Uri, tarDirectory, uploadFileToS3 } from "../s3Transport.js";

/** Options for {@link deploySite}. */
export interface DeploySiteOptions {
  /** Local project directory containing `index.html` (and any composition assets). */
  projectDir: string;
  /** S3 bucket the SAM stack / CDK construct provisioned. */
  bucketName: string;
  /** AWS region for the S3 client. Defaults to the SDK's default chain (env / config / IMDS). */
  region?: string;
  /**
   * Override the content-addressed site id. Useful when the caller has a
   * stable external identifier they want to use (e.g. a git SHA); if
   * unset, the hash of the project tree picks it.
   */
  siteId?: string;
  /** Injection seam for tests. Production callers leave unset. */
  s3?: S3Client;
}

/** Stable handle returned by {@link deploySite}. Pass back to {@link renderToLambda}. */
export interface SiteHandle {
  /** Content-addressed (or caller-supplied) identifier; stable across re-uploads of the same tree. */
  siteId: string;
  /** Bucket the site landed in. Surfaced separately so callers don't have to re-parse `projectS3Uri`. */
  bucketName: string;
  /** Full `s3://bucket/sites/<siteId>/project.tar.gz` URI; pass through to `renderToLambda`. */
  projectS3Uri: string;
  /** Tarball size in bytes; useful for "did we actually skip the upload?" assertions. */
  bytes: number;
  /** ISO timestamp of the most recent upload OR the existing object the short-circuit found. */
  uploadedAt: string;
  /** `false` if the object already existed and we skipped the PUT. */
  uploaded: boolean;
}

/**
 * Upload `projectDir` to `s3://bucketName/sites/<siteId>/project.tar.gz`.
 *
 * Short-circuits when an object with the same key already exists in the
 * bucket — `siteId` derives from the project's content hash, so the same
 * bytes produce the same key, and re-uploading would be redundant.
 */
export async function deploySite(opts: DeploySiteOptions): Promise<SiteHandle> {
  if (!statSync(opts.projectDir).isDirectory()) {
    throw new Error(`[deploySite] projectDir is not a directory: ${opts.projectDir}`);
  }

  const siteId = opts.siteId ?? hashProjectDir(opts.projectDir);
  const key = `sites/${siteId}/project.tar.gz`;
  const projectS3Uri = formatS3Uri({ bucket: opts.bucketName, key });
  const s3 = opts.s3 ?? new S3Client({ region: opts.region });

  // HeadObject short-circuit. Adopters re-rendering the same project on
  // a tight inner loop (CI smoke, demo flows) save the tar+gzip+PUT pass
  // on every iteration.
  const existing = await headObject(s3, opts.bucketName, key);
  if (existing) {
    return {
      siteId,
      bucketName: opts.bucketName,
      projectS3Uri,
      bytes: existing.bytes,
      uploadedAt: existing.lastModified,
      uploaded: false,
    };
  }

  const workdir = mkdtempSync(join(tmpdir(), "hf-deploy-site-"));
  try {
    const tarball = join(workdir, "project.tar.gz");
    await tarDirectory(opts.projectDir, tarball);
    // Note: tarDirectory packs *everything* under `cwd`. We don't need to
    // re-implement the skip list inside the tar pack because the
    // producer's plan stage applies the same skip during its copy; the
    // archive is slightly bigger than the planDir's compiled/ subtree
    // but the cost is bounded by the project's user-authored content.
    const size = statSync(tarball).size;
    await uploadFileToS3(s3, tarball, projectS3Uri, "application/gzip");
    return {
      siteId,
      bucketName: opts.bucketName,
      projectS3Uri,
      bytes: size,
      uploadedAt: new Date().toISOString(),
      uploaded: true,
    };
  } finally {
    rmSync(workdir, { recursive: true, force: true });
  }
}

async function headObject(
  s3: S3Client,
  bucket: string,
  key: string,
): Promise<{ bytes: number; lastModified: string } | null> {
  try {
    const res = await s3.send(new HeadObjectCommand({ Bucket: bucket, Key: key }));
    return {
      bytes: typeof res.ContentLength === "number" ? res.ContentLength : 0,
      lastModified:
        res.LastModified instanceof Date
          ? res.LastModified.toISOString()
          : new Date().toISOString(),
    };
  } catch (err) {
    // The SDK throws different error shapes for 404 vs 403 vs network;
    // a 404 means "needs upload" and is the most common case. Anything
    // else propagates so callers see auth / network failures.
    const status = (err as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode;
    if (status === 404) return null;
    const name = (err as { name?: string }).name;
    if (name === "NotFound" || name === "NoSuchKey") return null;
    throw err;
  }
}

