/**
 * Vitest setup: install a minimal in-memory BroadcastChannel polyfill so that
 * happy-dom tests can exercise the presenter/audience channel code path.
 * This polyfill is intentionally NOT shipped in production code.
 */

type MsgHandler = (event: MessageEvent) => void;

const registry = new Map<string, Set<InMemoryBroadcastChannel>>();

class InMemoryBroadcastChannel {
  onmessage: MsgHandler | null = null;
  readonly name: string;
  private _closed = false;

  constructor(name: string) {
    this.name = name;
    let set = registry.get(name);
    if (!set) {
      set = new Set();
      registry.set(name, set);
    }
    set.add(this);
  }

  // fallow-ignore-next-line complexity
  postMessage(data: unknown): void {
    if (this._closed) return;
    const peers = registry.get(this.name);
    if (!peers) return;
    for (const peer of peers) {
      if (peer === this) continue;
      peer.onmessage?.(new MessageEvent("message", { data }));
    }
  }

  close(): void {
    if (this._closed) return;
    this._closed = true;
    registry.get(this.name)?.delete(this);
  }
}

if (typeof globalThis.BroadcastChannel === "undefined") {
  (globalThis as Record<string, unknown>)["BroadcastChannel"] = InMemoryBroadcastChannel;
}

import { describe, expect, it } from "vitest";
import { computeDeVerifySampleFractions } from "./frameCapture.js";

describe("computeDeVerifySampleFractions", () => {
  it("pins the last sample at 95% so late-onset damage is sampled", () => {
    const fractions = computeDeVerifySampleFractions(4);
    expect(fractions).toEqual([0.25, 0.5, 0.75, 0.95]);
  });

  it("keeps the requested sample count", () => {
    for (const k of [1, 2, 3, 4, 8]) {
      expect(computeDeVerifySampleFractions(k)).toHaveLength(k);
    }
  });

  it("uses only the tail sample when k is 1", () => {
    expect(computeDeVerifySampleFractions(1)).toEqual([0.95]);
  });

  it("returns an empty grid when verification is disabled", () => {
    expect(computeDeVerifySampleFractions(0)).toEqual([]);
    expect(computeDeVerifySampleFractions(-2)).toEqual([]);
  });

  it("stays strictly increasing within (0, 1) for every supported k", () => {
    for (let k = 1; k <= 8; k++) {
      const fractions = computeDeVerifySampleFractions(k);
      for (let i = 0; i < fractions.length; i++) {
        const f = fractions[i] ?? 0;
        expect(f).toBeGreaterThan(0);
        expect(f).toBeLessThan(1);
        if (i > 0) expect(f).toBeGreaterThan(fractions[i - 1] ?? 0);
      }
    }
  });
});

function assert(condition: unknown, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

const ALLOWED_HOSTS = new Set(["runtime.example.com"]);
const ALLOWED_PATH_PREFIX = "/static/hyperframes-runtime/";

function isAllowedRuntimeUrl(candidate: string): boolean {
  try {
    const parsed = new URL(candidate);
    return (
      parsed.protocol === "https:" &&
      ALLOWED_HOSTS.has(parsed.hostname.toLowerCase()) &&
      parsed.pathname.startsWith(ALLOWED_PATH_PREFIX) &&
      parsed.pathname.endsWith(".js")
    );
  } catch {
    return false;
  }
}

function isGuardedPreviewMessage(data: unknown): boolean {
  if (!data || typeof data !== "object") {
    return false;
  }
  const record = data as { source?: unknown; type?: unknown };
  const source = typeof record.source === "string" ? record.source : null;
  const type = typeof record.type === "string" ? record.type : null;
  const guardedTypes = new Set([
    "state",
    "timeline",
    "element-picked",
    "element-picked-many",
    "element-pick-candidates",
    "pick-mode-cancelled",
  ]);
  if (!type || !guardedTypes.has(type)) {
    return false;
  }
  return source === "hf-preview";
}

const allowedRuntimeFixtures = [
  "https://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/hyperframes-runtime/v2026.02.20/hyperframe.runtime.iife.js",
];

const blockedRuntimeFixtures = [
  "http://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "javascript:alert(1)",
  "data:text/javascript,alert(1)",
  "https://evil.example/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/other/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.css",
];

for (const fixture of allowedRuntimeFixtures) {
  assert(isAllowedRuntimeUrl(fixture), `Expected runtime URL to be allowed: ${fixture}`);
}

for (const fixture of blockedRuntimeFixtures) {
  assert(!isAllowedRuntimeUrl(fixture), `Expected runtime URL to be blocked: ${fixture}`);
}

const allowedMessages = [
  { type: "state", source: "hf-preview" },
  { type: "timeline", source: "hf-preview" },
  { type: "element-picked", source: "hf-preview" },
];
const blockedMessages = [
  { type: "state", source: "hf-parent" },
  { type: "timeline", source: "evil-origin" },
  { type: "element-picked", source: "hf-parent" },
  { type: "pick-mode-cancelled", source: null },
  { type: "unknown-type", source: "hf-preview" },
];

for (const fixture of allowedMessages) {
  assert(
    isGuardedPreviewMessage(fixture),
    `Expected message fixture to pass guard: ${JSON.stringify(fixture)}`,
  );
}

for (const fixture of blockedMessages) {
  assert(
    !isGuardedPreviewMessage(fixture),
    `Expected message fixture to fail guard: ${JSON.stringify(fixture)}`,
  );
}

console.log(
  JSON.stringify({
    event: "hyperframe_runtime_security_fixtures_verified",
    allowedRuntimeFixtures: allowedRuntimeFixtures.length,
    blockedRuntimeFixtures: blockedRuntimeFixtures.length,
    allowedMessages: allowedMessages.length,
    blockedMessages: blockedMessages.length,
  }),
);

import { afterEach, describe, expect, it, vi } from "vitest";

// The module inspects `process.argv[1]` + `realpathSync`. We stub both so
// each test describes a hypothetical install layout without touching the
// filesystem.

type InstallerInfo =
  (typeof import("./installerDetection.js"))["detectInstaller"] extends () => infer R ? R : never;

async function detectWith(realPath: string | null): Promise<InstallerInfo> {
  vi.resetModules();
  const origArgv1 = process.argv[1];
  if (realPath === null) {
    process.argv[1] = "";
  } else {
    // argv[1] doesn't matter — realpathSync is what gets checked after the
    // resolver runs. Set it to the unresolved form and stub fs.realpathSync
    // to return the scenario's resolved path.
    process.argv[1] = "/not/used/at/runtime";
  }
  vi.doMock("node:fs", async () => {
    const actual = await vi.importActual<typeof import("node:fs")>("node:fs");
    return {
      ...actual,
      realpathSync:
        realPath === null
          ? () => {
              throw new Error("simulated unresolved path");
            }
          : () => realPath,
    };
  });

  const mod = await import("./installerDetection.js");
  const info = mod.detectInstaller();
  process.argv[1] = origArgv1 ?? "";
  return info;
}

describe("detectInstaller", () => {
  afterEach(() => {
    vi.doUnmock("node:fs");
    vi.resetModules();
  });

  it("classifies workspace link as skip (monorepo dev)", async () => {
    const info = await detectWith("/Users/dev/hyperframes-oss/packages/cli/dist/cli.js");
    expect(info.kind).toBe("skip");
    expect(info.reason).toContain("workspace");
    expect(info.installCommand("0.4.4")).toBeNull();
  });

  it("classifies npx _npx cache path as skip", async () => {
    const info = await detectWith(
      "/Users/me/.npm/_npx/abc123/node_modules/hyperframes/dist/cli.js",
    );
    expect(info.kind).toBe("skip");
    expect(info.reason.toLowerCase()).toContain("ephemeral");
  });

  it("classifies bunx temp dir as skip", async () => {
    const info = await detectWith("/var/folders/tmp/bunx-501-hyperframes/entry.js");
    expect(info.kind).toBe("skip");
    expect(info.reason.toLowerCase()).toContain("ephemeral");
  });

  it("detects Homebrew install", async () => {
    const info = await detectWith("/opt/homebrew/Cellar/hyperframes/0.4.3/bin/hyperframes");
    expect(info.kind).toBe("brew");
    expect(info.installCommand("0.4.4")).toBe("brew upgrade hyperframes");
  });

  it("detects bun global install", async () => {
    const info = await detectWith(
      "/Users/me/.bun/install/global/node_modules/hyperframes/dist/cli.js",
    );
    expect(info.kind).toBe("bun");
    expect(info.installCommand("0.4.4")).toBe("bun add -g hyperframes@0.4.4");
  });

  it("detects pnpm global install (Library/pnpm path)", async () => {
    const info = await detectWith(
      "/Users/me/Library/pnpm/global/5/node_modules/hyperframes/dist/cli.js",
    );
    expect(info.kind).toBe("pnpm");
    expect(info.installCommand("0.4.4")).toBe("pnpm add -g hyperframes@0.4.4");
  });

  it("treats pnpm project-local installs as unknown layouts", async () => {
    const info = await detectWith(
      "/path/to/project/node_modules/.pnpm/hyperframes@0.4.3/node_modules/hyperframes/dist/cli.js",
    );
    expect(info.kind).toBe("skip");
    expect(info.installCommand("0.4.4")).toBeNull();
  });

  it("detects npm global install", async () => {
    const info = await detectWith("/usr/local/lib/node_modules/hyperframes/dist/cli.js");
    expect(info.kind).toBe("npm");
    expect(info.installCommand("0.4.4")).toBe("npm install -g hyperframes@0.4.4");
  });

  it("detects npm global install on Windows", async () => {
    const info = await detectWith(
      "C:\\Users\\me\\AppData\\Roaming\\npm\\node_modules\\hyperframes\\dist\\cli.js",
    );
    expect(info.kind).toBe("npm");
    expect(info.installCommand("0.4.4")).toBe("npm install -g hyperframes@0.4.4");
  });

  it("returns skip when the entry cannot be resolved", async () => {
    const info = await detectWith(null);
    // realpathSync throws → reason is "could not resolve" OR the path itself
    // (the fallback returns the unresolved argv[1]); either way the kind is
    // skip-or-unknown which we treat as skip downstream.
    expect(info.kind).toBe("skip");
    expect(info.installCommand("0.4.4")).toBeNull();
  });

  it("returns skip for an unknown install layout", async () => {
    const info = await detectWith("/some/random/path/hyperframes");
    expect(info.kind).toBe("skip");
    expect(info.reason).toMatch(/Unknown install layout/);
  });
});

import { installInvocation } from "./installerDetection.js";

describe("installInvocation", () => {
  it("returns the npm global argv for kind npm", () => {
    expect(installInvocation("npm", "1.2.3")).toEqual({
      bin: "npm",
      args: ["install", "-g", "hyperframes@1.2.3"],
    });
  });

  it("returns bun/pnpm add -g argv for those managers", () => {
    expect(installInvocation("bun", "1.2.3")).toEqual({
      bin: "bun",
      args: ["add", "-g", "hyperframes@1.2.3"],
    });
    expect(installInvocation("pnpm", "1.2.3")).toEqual({
      bin: "pnpm",
      args: ["add", "-g", "hyperframes@1.2.3"],
    });
  });

  it("returns a version-less brew upgrade for kind brew", () => {
    expect(installInvocation("brew", "1.2.3")).toEqual({
      bin: "brew",
      args: ["upgrade", "hyperframes"],
    });
  });

  it("returns null for kind skip (ephemeral / project-local / unknown)", () => {
    expect(installInvocation("skip", "1.2.3")).toBeNull();
  });
});

